import os

from django.contrib.auth import get_user_model

from .adapters import AccountAdapter


class OpenshipAccountAdapter(AccountAdapter):
    """Self-hosted default: only the first account can sign up.

    BrightBean Chat gives every sign-up its own organization, so an internet-
    facing install would let anyone create one. The first account becomes the
    owner and sign-up then closes; set OPEN_SIGNUP=true to keep it open.
    """

    def is_open_for_signup(self, request):
        if os.environ.get("OPEN_SIGNUP", "false").strip().lower() == "true":
            return True
        return not get_user_model().objects.exists()
